 protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);gid=getIntent().getStringExtra("group");JSONObject g=LocalGroups.get(gid);if(g==null){finish();return;}selection=new FileSelection(this,"live_"+gid,this::refreshSelection);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);LinearLayout head=Ui.topBar(this,g.optString("name"),true,null);TextView info=Ui.t(this,"ⓘ",23,Ui.accent,App.cairoB);head.addView(info);info.setOnClickListener(v->details());TextView chatMenu=Ui.t(this,"⋮",25,Ui.text,App.cairoB);chatMenu.setContentDescription(getString(R.string.chat_options));Ui.pad(chatMenu,12,8,12,8,this);head.addView(chatMenu);chatMenu.setOnClickListener(v->ChatActions.show(this,"live_"+gid,()->{selection.back();refreshSelection();}));root.addView(head);status=Ui.sub(this,getString(R.string.group_live_note));root.addView(status);if(LocalGroups.isHost(g)){TextView inviteButton=Ui.ghost(this,getString(R.string.invite_member));root.addView(inviteButton);inviteButton.setOnClickListener(v->invite());}scroll=new ScrollView(this);rows=Ui.col(this);Ui.pad(rows,16,6,16,10,this);scroll.addView(rows);root.addView(scroll,Ui.lpW1());LinearLayout bar=Ui.row(this);Ui.pad(bar,12,9,12,14,this);TextView attach=Ui.t(this,"＋",28,Ui.dim,App.cairo);attach.setContentDescription(getString(R.string.send_files));bar.addView(attach,Ui.lp(Ui.dp(this,44),Ui.dp(this,44)));attach.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);i.setType("*/*");startActivityForResult(i,73);});TextView emoji=Ui.t(this,"☺",25,Ui.dim,App.cairo);LinearLayout.LayoutParams emojiLp=Ui.lp(Ui.dp(this,44),Ui.dp(this,44));emojiLp.setMarginStart(Ui.dp(this,12));bar.addView(emoji,emojiLp);EditText input=new EditText(this);input.setTextColor(Ui.text);input.setHintTextColor(Ui.dim);input.setHint(R.string.message_hint);input.setTextSize(14);input.setBackground(Ui.round(Ui.field,22,this));Ui.pad(input,14,8,14,8,this);bar.addView(input,Ui.lpw(1));emoji.setOnClickListener(v->EmojiPicker.show(this,input));TextView send=new ComposerButton(this);bar.addView(send,Ui.lp(Ui.dp(this,44),Ui.dp(this,44)));send.setContentDescription(getString(R.string.send_now));send.setOnClickListener(v->{String text=input.getText().toString().trim();if(text.isEmpty())return;input.setText("");work.execute(()->{try{LocalGroups.sendText(gid,text);}catch(Exception e){error(e);}runOnUiThread(this::render);});});voice=new VoiceRecorder(this,send,input,(uri,name,size)->work.execute(()->{try{LocalGroups.sendRecordedVoice(gid,uri,name,size);runOnUiThread(this::render);}catch(Exception e){error(e);}}));send.setText("🎙");input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){send.setText(s.length()==0?"🎙":"➤");send.setContentDescription(getString(s.length()==0?R.string.voice_hold:R.string.send_now));}public void afterTextChanged(android.text.Editable e){}});
        root.addView(bar);setContentView(root);if(!g.optBoolean("joined"))new AppDialog(this).setTitle(R.string.join_group).setMessage(getString(R.string.group_join_note,g.optString("hostName"))).setNegativeButton(R.string.cancel,(d,n)->finish()).setPositiveButton(R.string.join_group,(d,n)->work.execute(()->{try{LocalGroups.join(gid);runOnUiThread(this::render);}catch(Exception e){error(e);}})).show();}
