 void details(){JSONObject g=LocalGroups.get(gid);if(g==null)return;StringBuilder text=new StringBuilder(getString(R.string.group_roles_note));text.append("\n").append(getString(R.string.group_creator)).append(": ").append(LocalGroups.isHost(g)?Profile.local().optString("name"):g.optString("hostName"));JSONArray members=g.optJSONArray("members");if(members!=null)for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m!=null)text.append("\n").append(m.optString("name")).append(LocalGroups.memberPending(gid,m.optString("id"))?getString(R.string.member_delete_pending):m.optBoolean("joined")?" ✓":" …");}AlertDialog.Builder d=new AppDialog(this).setTitle(g.optString("name")).setMessage(text.toString()).setNegativeButton(android.R.string.ok,null);if(LocalGroups.isHost(g))d.setNeutralButton(R.string.delete_group,(dialog,which)->new AppDialog(this).setTitle(R.string.delete_group).setMessage(R.string.delete_group_note).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(confirm,n)->work.execute(()->{try{LocalGroups.deleteGroup(gid);runOnUiThread(this::finish);}catch(Exception e){error(e);}})).show());if(LocalGroups.isHost(g))d.setPositiveButton(R.string.invite_member,(a,n)->invite());d.show();}
 void invite(){JSONArray peers=Store.peers();if(peers.length()==0){new AppDialog(this).setMessage(R.string.group_pair_first).setPositiveButton(android.R.string.ok,null).show();return;}String[] names=new String[peers.length()];for(int i=0;i<names.length;i++)names[i]=peers.optJSONObject(i).optString("name");new AppDialog(this).setTitle(R.string.invite_member).setItems(names,(d,n)->new AppDialog(this).setMessage(getString(R.string.invite_confirm,names[n])).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.invite_member,(a,k)->work.execute(()->{try{LocalGroups.invite(gid,peers.optJSONObject(n));runOnUiThread(()->Toast.makeText(this,R.string.invite_sent,0).show());}catch(Exception e){error(e);}})).show()).show();}
 private boolean preserveSelectionScroll;private void refreshSelection(){if(rows==null)return;int y=scroll.getScrollY();java.util.HashSet<String> live=new java.util.HashSet<>();JSONArray saved=Store.thread("live_"+gid);for(int j=0;j<saved.length();j++){JSONObject item=saved.optJSONObject(j);if(item!=null)live.add(FileSelection.key(item));}for(int i=rows.getChildCount()-1;i>=0;i--){android.view.View row=rows.getChildAt(i);if(row.getTag() instanceof JSONObject&&!live.contains(FileSelection.key((JSONObject)row.getTag())))rows.removeViewAt(i);}last=saved.toString();for(int i=0;i<rows.getChildCount();i++){android.view.View row=rows.getChildAt(i);Object tag=row.getTag();if(tag instanceof JSONObject){JSONObject m=(JSONObject)tag;{row.setBackground(selection.has(m)?Ui.round(0x3058a4ff,12,this):null);row.setOnClickListener(selection.active()?v->selection.toggle(m):null);}}invalidateSelection(row);}scroll.post(()->scroll.scrollTo(0,y));}private void invalidateSelection(android.view.View v){v.invalidate();if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)invalidateSelection(g.getChildAt(i));}}
 private String last="";void render(){JSONObject current=LocalGroups.get(gid);if(current==null||current.optBoolean("deleted")){finish();return;}int waiting=LocalGroups.pending(gid);status.setText(waiting>0?getString(R.string.group_delete_pending,waiting):getString(R.string.group_live_note));JSONArray t=Store.thread("live_"+gid);String now=t.toString();if(now.equals(last))return;last=now;VoicePlayer.release(this);rows.removeAllViews();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m==null)continue;boolean me=m.optBoolean("me");LinearLayout cell=selection.row(m);cell.setTag(m);if(selection.has(m))cell.setBackground(Ui.round(0x3058a4ff,12,this));if(selection.active()&&!m.optString("kind").equals("deleted"))cell.setOnClickListener(v->selection.toggle(m));cell.setGravity(me?android.view.Gravity.END:android.view.Gravity.START);cell.addView(Ui.t(this,m.optString("senderName"),11,Ui.accent,App.cairoSB));if(m.optString("kind").equals("deleted")){cell.addView(Ui.t(this,getString(R.string.group_file_deleted,m.optString("actor")),13,Ui.dim,App.cairo));}else if(m.optString("kind").equals("file")){android.view.View card=FileCards.card(this,m,()->selection.toggle(m),()->fileMenu(m));cell.addView(selection.decorate(card,m));if((m.optString("state").startsWith("failed")||m.optString("state").matches(".*[1-9][0-9]* failed.*"))&&(LocalGroups.isHost(current)||LocalGroups.self().equals(m.optString("sender")))){TextView retry=Ui.ghost(this,getString(R.string.retry_file));cell.addView(retry);retry.setOnClickListener(v->retry(m));}}else{TextView b=Ui.t(this,m.optString("body"),15,Ui.text,App.cairo);b.setMaxWidth(Ui.dp(this,285));b.setBackground(Ui.round(me?0xff203d52:Ui.card,15,this));Ui.pad(b,13,9,13,9,this);b.setOnLongClickListener(v->{selection.toggle(m);return true;});cell.addView(b);}cell.addView(Ui.t(this,m.optString("state"),10,Ui.dim,App.cairo));Ui.pad(cell,0,5,0,9,this);LinearLayout.LayoutParams gap=Ui.lp(-1,-2);gap.bottomMargin=Ui.dp(this,8);rows.addView(cell,gap);}if(!preserveSelectionScroll)scroll.post(()->scroll.fullScroll(android.view.View.FOCUS_DOWN));Store.set("groupRead_"+gid,String.valueOf(System.currentTimeMillis()));}
 void retry(JSONObject m){work.execute(()->{try{LocalGroups.retryFile(gid,m);runOnUiThread(this::render);}catch(Exception e){error(e);}});}
 void fileMenu(JSONObject m){JSONObject g=LocalGroups.get(gid);java.util.ArrayList<String> labels=new java.util.ArrayList<>();java.util.ArrayList<Integer> codes=new java.util.ArrayList<>();int[] base={R.string.open_file,R.string.open_folder,R.string.share_file,R.string.select_file,R.string.delete_local_files};for(int i=0;i<base.length;i++){labels.add(getString(base[i]));codes.add(i);}labels.add(getString(R.string.forward_file));codes.add(7);if(LocalGroups.isHost(g)||LocalGroups.self().equals(m.optString("sender"))){labels.add(getString(R.string.retry_file));codes.add(5);}if(LocalGroups.canDelete(g,m)){labels.add(getString(R.string.delete_everyone));codes.add(6);}new AppDialog(this).setTitle(m.optString("name")).setItems(labels.toArray(new String[0]),(dialog,n)->{int code=codes.get(n);if(code==7)FileCards.forward(this,m);if(code==0)FileCards.open(this,m);if(code==1)Attachments.folder(this,m);if(code==2)FileCards.share(this,m);if(code==3)selection.toggle(m);if(code==4)selection.deleteLocal(m);if(code==5)retry(m);if(code==6)new AppDialog(this).setTitle(R.string.delete_everyone).setMessage(R.string.group_delete_file_note).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(confirm,k)->work.execute(()->{try{LocalGroups.deleteFile(gid,m.getString("id"));runOnUiThread(this::render);}catch(Exception e){error(e);}})).show();}).show();}
 public void onBackPressed(){if(EmojiPicker.dismiss(this))return;if(selection!=null&&selection.back())return;super.onBackPressed();}
 protected void onResume(){super.onResume();handler.post(tick);}protected void onPause(){if(voice!=null)voice.cancel();VoicePlayer.release(this);last="";handler.removeCallbacksAndMessages(null);super.onPause();}protected void onDestroy(){if(voice!=null)voice.cancel();VoicePlayer.release(this);EmojiPicker.dismiss(this);work.shutdownNow();super.onDestroy();}
 protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(selection!=null&&selection.activityResult(q,r))return;if(q!=73||r!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}work.execute(()->{try{String name="file";long size=-1;try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int ni=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),si=c.getColumnIndex(OpenableColumns.SIZE);if(ni>=0)name=c.getString(ni);if(si>=0&&!c.isNull(si))size=c.getLong(si);}}LocalGroups.sendFile(gid,uri,name,size);runOnUiThread(this::render);}catch(Exception e){error(e);}});}
